/* 90_VERIFY — 읽기 전용. 각 조회의 기대값 확인
 * 패키지 SCP0111_CLOUD_DB_MOD_20261103_1021 · 생성 tools/CloudPkg/cloud_pkg.py 1.0.0 · 2026-11-03 10:21
 * 실행 계정 = SCM_MGR (전체 F5 · 반복 실행 안전)
 */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 코드 객체 — 전부 VALID */
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PKG_SCP0111') ORDER BY 1, 2;

/* 2) 컴파일 오류 — 0건 */
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_SCP0111') ORDER BY NAME, TYPE, SEQUENCE;

/* 3) GTT 구조 — 0건(사내와 다른 GTT 가 있으면 행) */
SELECT E.T AS TABLE_NAME
  FROM (SELECT 'GT_SCP0111_CELL_ELEC_MAP' T, 'DIVISION_ID_CS|VARCHAR2|120|||Y;COMPANY_ID_CS|VARCHAR2|120|||Y;PLANT_ID_CS|VARCHAR2|120|||Y;CELL_PLANT_PRIORITY|NUMBER|0|||Y;PLANT_ID_ES|VARCHAR2|120|||Y;SITE_DESCRIPTION_ES|VARCHAR2|600|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_ELEC_PLANT' T, 'COMPANY_ID|VARCHAR2|120|||Y;DIVISION_ID|VARCHAR2|120|||Y;CITY|VARCHAR2|400|||Y;COUNTRY|VARCHAR2|400|||Y;PLANT_ID|VARCHAR2|120|||Y;SITE_DESCRIPTION|VARCHAR2|600|||Y;SCM_SITE_ID|VARCHAR2|120|||Y;SITE_ID|VARCHAR2|120|||Y;PRIORITY_1ST|NUMBER|0|||Y;PRIORITY_2ND|NUMBER|0|||Y;PRIORITY_3RD|NUMBER|0|||Y;PRIORITY_4TH|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_PSI_230' T, 'DIVISION_ID|VARCHAR2|40|||Y;PLANT_ID|VARCHAR2|40|||Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;ITEM_ID|VARCHAR2|160|||Y;YYYYMM|VARCHAR2|24|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_PSI_CELL' T, 'DIVISION_ID|VARCHAR2|40|||Y;PLANT_ID|VARCHAR2|40|||Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;YYYYMM|VARCHAR2|24|||Y;CHILD_ITEM_ID|VARCHAR2|600|||Y;ACCUMULATED_CHILD_QTY|NUMBER|0|||Y;YIELD|NUMBER|0|||Y;REAL_MODI_QTY|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_PSI_CHILD' T, 'DIVISION_ID|VARCHAR2|40|||Y;PLANT_ID|VARCHAR2|40|||Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;YYYYMM|VARCHAR2|24|||Y;CHILD_ITEM_ID|VARCHAR2|600|||Y;REAL_MODI_QTY|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_PSI_TGT' T, 'DIVISION_ID|VARCHAR2|40|||Y;PLANT_ID|VARCHAR2|40|||Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;YYYYMM|VARCHAR2|24|||Y;ITEM_ID|VARCHAR2|160|||Y;TARGET_ITEM_ID|VARCHAR2|600|||Y;REAL_MODI_QTY|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_TCO_ITEM' T, 'TCO_ITEM_PROD|VARCHAR2|600|||Y;CELL_ITEM_PROD|VARCHAR2|600|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0111_YIELD_P' T, 'DIVISION_ID|VARCHAR2|120|||Y;COMPANY_ID|VARCHAR2|120|||Y;PLANT_ID|VARCHAR2|120|||Y;LINE_ID|VARCHAR2|120|||Y;MONTH|VARCHAR2|24|||Y;ITEM_ID|VARCHAR2|600|||Y;YIELD|NUMBER|0|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0111' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '화면 전용 API' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0111_essPackLine_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SAVE_ADMIN' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SEARCH' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'P_SCP0111_GET' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0111_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'P_SCP0111_SAVE_ADMIN' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0111' MNU_ID, 'essPackLine' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
