    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'SAVEDETAIL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S;
