/* 5) 클라우드에만 있는 화면 META 행(사내에 없음) — 참고. 지우지 않음 */
SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'SCP0111' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0111_essPackLine_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SAVE_ADMIN' API_ID FROM DUAL
    UNION ALL SELECT 'SCP0111_integrationPsi_SEARCH' API_ID FROM DUAL) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, T.MNU_ID, T.SHT_NM, T.MNU_BTN_CD
  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
 WHERE (MNU_ID = 'SCP0111')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0111' MNU_ID, 'essPackLine' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'EXCEL' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0111' MNU_ID, 'main' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
