    UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'lineId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0111.P_SCP0111_SAVE_PSI_ADMIN' PROC_NM, 'measure' COL_NM, 'IN' COL_TP_CD FROM DUAL
