   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0111' PROGRAM_ID, 'Integration PSI' SHEET_NAME, 'BOH_QTY' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0111' PROGRAM_ID, 'Integration PSI' SHEET_NAME, 'CELL_CF' COLUMN_NAME FROM DUAL
